import json,glob,os,re,collections
base='/root/.claude/projects/-home-user-fortress/fe616d40-a9c6-56d7-9da1-7168a172765d/subagents/workflows'
tasks={}  # id -> dict
pending={}  # tool_use_id -> info
upd=[]
for run in sorted(os.listdir(base)):
    for f in sorted(glob.glob(f'{base}/{run}/agent-*.jsonl')):
        meta=json.load(open(f[:-6]+'.meta.json')); lab=meta.get('description')
        ag=os.path.basename(f)[6:-6]
        for i,line in enumerate(open(f),1):
            d=json.loads(line)
            if d.get('type')=='assistant':
                for b in d['message']['content']:
                    if b.get('type')=='tool_use' and b['name'] in('TaskCreate','TaskUpdate'):
                        pending[b['id']]=(b['name'],b['input'],run,ag,lab,i,d['timestamp'])
            elif d.get('type')=='user' and isinstance(d['message']['content'],list):
                for b in d['message']['content']:
                    if b.get('type')=='tool_result' and b.get('tool_use_id') in pending:
                        nm,inp,run_,ag_,lab_,ln,ts=pending[b['tool_use_id']]
                        res=json.dumps(b.get('content'))
                        if nm=='TaskCreate':
                            m=re.search(r'Task #(\d+) created',res)
                            if m:
                                tid=int(m.group(1))
                                tasks[tid]=dict(id=tid,run=run_,agent=ag_,label=lab_,line=ln,ts=ts,subject=inp.get('subject'),desc=inp.get('description'),ups=[])
                            else: print('create-nomatch',res[:100])
                        else:
                            upd.append((int(inp['taskId']),inp.get('status'),inp,run_,ag_,lab_,ln,ts,res[:80]))
for u in upd:
    tid=u[0]
    if tid in tasks: tasks[tid]['ups'].append(dict(status=u[1],keys=[k for k in u[2] if k!='taskId'],run=u[3],agent=u[4],label=u[5],line=u[6],ts=u[7],res=u[8]))
    else: print('update for unknown',u[:2],u[3:6])
json.dump(tasks,open('tasks.json','w'))
print(len(tasks),min(tasks),max(tasks))
# anomalies
for t in sorted(tasks.values(),key=lambda t:t['id']):
    sts=[u['status'] for u in t['ups']]
    cross=[u for u in t['ups'] if u['agent']!=t['agent']]
    last=sts[-1] if sts else 'pending'
    if last!='completed' or cross:
        print(t['id'],t['run'][3:11],t['label'],t['agent'][:8],'ups',sts,'cross',[(u['agent'][:8],u['label'],u['status']) for u in cross])
EOF
python3 tasks.py

