    if run[3:] in batch:
        for k,v in r.items(): tot[k]+=v
allin=tot['ctx_in']+tot['ctx_cacheread']+tot['ctx_cachewrite']
print('TOTAL b14-19',{k:int(v) for k,v in tot.items()}, 'allin',int(allin),'rem share %.1f%%'%(100*(tot['rem_tok']+tot['rem_reread'])/allin),'taskcall share %.2f%%'%(100*(tot['tc_tok']+tot['tc_reread'])/allin))
